def _deep_health_networks():
    """Return the explicitly trusted deep-health source networks."""
    raw = os.getenv(
        "DEEP_HEALTH_TRUSTED_CIDRS",
        "172.17.0.1/32",
    )
    networks = []
    for value in raw.split(","):
        value = value.strip()
        if not value:
            continue
        try:
            networks.append(ipaddress.ip_network(value, strict=False))
        except ValueError:
            continue
    return tuple(networks)


def _deep_health_allowed():
    """Allow deep details for loopback and explicit trusted networks only.

    The request address is resolved by trusted-proxy configuration, preventing
    spoofed forwarded addresses from entering the explicit CIDR allowlist.
    """
    from flask import request
    try:
        addr = ipaddress.ip_address(request.remote_addr or "")
    except ValueError:
        return False
    return addr.is_loopback or any(
        addr in network for network in _deep_health_networks()
    )


def _capacity_snapshot():
    """DB havuzu + sunum kapasitesinin anlık görünümü (deep health + metrikler).

    Sunum kapasitesi ile DB havuzu kapasitesi AYRI iki sayıdır ve birbirinden
    habersiz ayarlanabilir; prod-hardening §6 "DB pool sizing aligned with maximum
    process/thread concurrency" tam olarak bu ikisinin uyumunu ister. Burada ikisi
    YAN YANA raporlanır ki uyumsuzluk gözle görülsün (hizalamanın kendisi PR4).

    Herhangi bir alan çözülemezse o alan atlanır — sağlık yanıtı ASLA bu yüzden
    düşmez (havuz iç görüsü SQLAlchemy sürümüne bağlı bir ayrıntıdır).
    """
    from app.services import ai_gate
    live = ai_gate.capacity_snapshot()
    snapshot = {
        "workers": ai_gate.WEB_WORKERS,
        "threads": ai_gate.WEB_THREADS,
        "ai_max_concurrency": ai_gate.AI_MAX_CONCURRENCY,
        "ai_model_max_concurrency": ai_gate.AI_MODEL_MAX_CONCURRENCY,
        "scrape_max_concurrency": ai_gate.SCRAPE_MAX_CONCURRENCY,
        # PR4: yapılandırılmış tavanların YANINDA ölçülen anlık kullanım.
        "ai_active": live["ai_active"],
        "ai_model_active": live["model_active"],
        "scrape_active": live["scrape_active"],
        "thread_reserve": live["thread_reserve"],
        "thread_reserve_floor": live["thread_reserve_floor"],
    }
    try:
        pool = db.engine.pool
        snapshot["db_pool"] = {
            "size": pool.size(),
            "checked_out": pool.checkedout(),
            "overflow": pool.overflow(),
        }
    except Exception:
        pass  # SQLite/StaticPool ya da sürüm farkı — kapasite görünümü opsiyonel
    return snapshot


def _record_capacity_gauges(snapshot):
    """Kapasite anlık görünümünü metrik olarak da yaz (deep-health probe'unda).

    Deploy gate ve konteyner probe'u bu ucu zaten düzenli çağırıyor; ayrı bir
    zamanlayıcı eklemek yerine var olan periyodikliği kullanıyoruz.
    """
    try:
        from app.services import runtime_metrics
        pool = snapshot.get("db_pool")
        if not pool:
            return
        runtime_metrics.set_gauge("DbPoolCheckedOut", pool["checked_out"])
        runtime_metrics.set_gauge("DbPoolOverflow", pool["overflow"])
        runtime_metrics.set_gauge("DbPoolSize", pool["size"])
    except Exception:
        pass


def _record_dependency_gauges(body):
    """Bağımlılık sağlığını 0/1 gauge olarak yaz (alarm eşiği kurulabilsin).

    Metin durumlar ("ok"/"degraded"/"offline") loglar ve insanlar içindir; alarm
    kuralları sayı ister. Boyut YOK: bunlar süreç-geneli tekil sinyaller.
    """
    try:
        from app.services import runtime_metrics
        runtime_metrics.set_gauge("DbUp", 1 if body.get("db") == "ok" else 0)
        runtime_metrics.set_gauge(
            "RedisUp", 1 if body.get("redis") == "ok" else 0)
        runtime_metrics.set_gauge(
            "LoginUp", 1 if body.get("login") == "ok" else 0)
        runtime_metrics.set_gauge(
            "LimiterDegraded",
            1 if body.get("limiter_storage") == "degraded" else 0)
    except Exception:
        pass


def _install_capacity_sampling(app):
    """Kapasite seviyelerini periyodik flush thread'inden örnekle (PR4).

    İki boşluğu birlikte kapatır:
    1. `ThreadReserve` — MOBILE_AUTH_ENABLED yaşam döngüsü kaydı ve
       docs/ROLLOUT.md rollout'u durdurma sinyali olarak bu gauge'a atıf yapıyordu
       ama gauge HİÇ yayınlanmıyordu (belgelenmiş ama var olmayan abort kapısı).
    2. `DbPool*` — yalnızca `/health?deep=1` yolunda yazılıyordu; o uç düzenli
       poll EDİLMEZ (konteyner probe'u sığ /health'i çağırır), dolayısıyla alarm
       INSUFFICIENT_DATA'da kalıyordu.

    Örnekleyici AĞ'a ÇIKMAZ: yalnızca süreç-içi semafor sayaçlarını ve havuzun
    kendi sayaçlarını okur. `DbUp`/`RedisUp`/`LoginUp` BİLEREK burada değildir —
    onlar gerçek bağımlılık probe'u gerektirir ve flush thread'inden çağrılırsa
    metrik yolu ağ'a çıkmış olurdu (bkz. docs/CAPACITY.md "Bilinen sınırlar").
    """
    from app.services import ai_gate, runtime_metrics

    def _sample():
        ai_gate.record_capacity_gauges()
        try:
            with app.app_context():
                pool = db.engine.pool
                runtime_metrics.set_gauge("DbPoolCheckedOut", pool.checkedout())
                runtime_metrics.set_gauge("DbPoolOverflow", pool.overflow())
                runtime_metrics.set_gauge("DbPoolSize", pool.size())
        except Exception:
            pass  # SQLite/StaticPool ya da sürüm farkı — havuz görünümü opsiyonel

    runtime_metrics.register_sampler(_sample)
    runtime_metrics.install_shutdown_flush()


def create_app():
    app = Flask(
        __name__,
        template_folder=os.path.join(_BASE_DIR, "templates"),
        static_folder=os.path.join(_BASE_DIR, "static"),
    )
    configure_app(app)

    from app.observability import init_sentry
    init_sentry(app)  # SENTRY_DSN yoksa no-op

    db.init_app(app)
    migrate.init_app(app, db)
    login_manager.init_app(app)

    register_blueprints(app)
    register_cognito(app)

    @app.route("/health")
    def health():
        # Konteyner sağlık kontrolü (Docker HEALTHCHECK) + deploy health-gate.
        # DB erişilemezse gerçek her istek 500'lenir; bu durumda /health de 503
        # dönmeli ki bozuk deploy otomatik rollback tetiklesin ve izleme fark etsin.
        # limiter_storage: "redis"/"memory"/"degraded" — "degraded" iken brute-force
        # login throttle süreç-yerel + geçici olur; DB'nin aksine tek başına
        # unhealthy saymayız (uygulama zarifçe bellek-yedeğine düşer, sadece sinyal).
        from flask import request
        from sqlalchemy import text
        import app.extensions as ext
        try:
            db.session.execute(text("SELECT 1"))
            db_ok = True
        except Exception:
            db.session.rollback()
            db_ok = False
        body = {
            "status": "ok" if db_ok else "error",
            "db": "ok" if db_ok else "error",
            "limiter_storage": ext.limiter_storage_status(),
        }
        status = 200 if db_ok else 503
        # I2/I3: ?deep=1 — deploy gate / harici readiness probe'u için derin
        # görünüm. Redis-down + LOGIN_FAIL_CLOSED=1 iken login %100 kapalıdır;
        # sığ /health yeşil kalır (liveness: konteyner restart-loop'a girmesin)
        # ama derin görünüm 503 döner ki gate "yeşilken login kapalı" yakalasın.
        #
        # M3: derin görünüm YALNIZCA iç ağdan verilir. İçerik iç duruşu ifşa eder
        # (login offline mı, Redis ayakta mı, Bedrock açık mı) ve her çağrıda bir
        # DIŞ HTTP isteği (FatSecret proxy) tetikler. Anonim biri "login: offline"ı
        # izleyerek Redis'in düştüğü ve login'in fail-closed olduğu ANI öğrenirdi.
        # Dışarıya 403 DEĞİL, sığ gövde döneriz — 403'ün kendisi de bir sinyal olurdu.
        if request.args.get("deep") == "1" and _deep_health_allowed():
            body["redis"] = {"redis": "ok", "memory": "unconfigured"}.get(
                body["limiter_storage"], "error")
            login_ok = (not app.config.get("LOGIN_FAIL_CLOSED", True)
                        or ext.login_throttle_available())
            body["login"] = "ok" if login_ok else "offline"
            body["bedrock"] = ("enabled" if app.config.get("BEDROCK_ENABLED")
                               else "disabled")
            # WS8: worker canlılığı BİLGİLENDİRİCİ (gating DEĞİL). Worker yoksa
            # arka-plan işleri satır-içine düşer; deploy'u düşürmez. None=bilinmiyor
            # (Redis yok), True/False=heartbeat penceresinde worker görüldü/görülmedi.
            from app.jobs import worker_alive
            alive = worker_alive()
            body["worker"] = ("unknown" if alive is None
                              else "alive" if alive else "down")
            # I4: FatSecret loopback proxy'si (host, 127.0.0.1:3000) süpervizörsüz
            # bir SPOF — düşerse makro çözümü sessizce LLM tahminine düşer.
            # BİLGİLENDİRİCİ alan: hata deploy gate'ini düşürmez (proxy kesintisi
            # app rollback'i gerektirmez), yalnızca izleme/deploy logunda görünür.
            import app.config as config_mod
            if not config_mod.FATSECRET_BASE_URL:
                body["fatsecret_proxy"] = "unconfigured"
            else:
                import requests
                try:
                    r = requests.get(
                        config_mod.FATSECRET_BASE_URL.rstrip("/") + "/rest/server.api",
                        timeout=3)
                    # Canlı proxy auth'suz istekte 4xx döner; nginx 502 = proxy ölü.
                    body["fatsecret_proxy"] = "ok" if r.status_code < 500 else "error"
                except Exception:
                    body["fatsecret_proxy"] = "error"
            # Rollout bayraklarının O ANKİ durumu. Bayraklar host .env'inde yaşar
            # ve deploy pipeline'ı onları TAŞIMAZ (bkz. docs/ROLLOUT.md) — yani
            # "canlıda ne açık?" sorusunun repodan yanıtı YOKTUR. Yalnızca ad +
            # boolean; sır/bağlantı dizesi/anahtar ASLA. Zaten iç-ağ sınırlı.
            import app.config as _config_mod
            body["flags"] = _config_mod.feature_flag_state(app)
            # Kimlik doğrulama sözleşmesinin O ANKİ hâli — bayraklarla aynı
            # gerekçe: leeway host .env'inde yaşar, repodan okunamaz. Yalnızca
            # ad + tamsayı; token/başlık/kullanıcı ASLA (docs/AUTH_CONTRACT.md).
            from app.services.auth_contract import contract_state
            body["auth_contract"] = contract_state()
            body["capacity"] = _capacity_snapshot()
            _record_capacity_gauges(body["capacity"])
            _record_dependency_gauges(body)
            if not login_ok:
                body["status"] = "error"
                status = 503
        return body, status

    # before_request order must match the original monolith:
    #   _csrf_protect -> (limiter) _check_request_limit -> maybe_weekly_rollover -> update_streak
    from app.hooks import _csrf_protect, generate_csp_nonce, inject_csp_nonce, \
        inject_csrf_token, inject_i18n, inject_nav, maybe_weekly_rollover, \
        set_csp_header, update_streak, inject_rank, ratelimit_exceeded, \
        not_found, payload_too_large, server_error
    from app.i18n import resolve_locale
    from app.observability import assign_request_id, log_request, start_request_timer
    # İstek süresini en baştan ölç + izleme kimliği ata (diğer before_request'lerden önce).
    app.before_request(start_request_timer)
    app.before_request(assign_request_id)
    app.before_request(generate_csp_nonce)
    app.before_request(_csrf_protect)
    limiter.init_app(app)
    warn_if_limiter_degraded(app)
    from app.services.ai_gate import enforce_gate_invariants
    enforce_gate_invariants(app)
    _install_capacity_sampling(app)
    app.before_request(maybe_weekly_rollover)
    app.before_request(update_streak)
    # Dil çözümü (g.locale): current_user/session'a bağlı, şablon render'dan önce.
    app.before_request(resolve_locale)
    app.context_processor(inject_csp_nonce)
    app.context_processor(inject_csrf_token)
    app.context_processor(inject_i18n)
    app.context_processor(inject_nav)
    app.context_processor(inject_rank)
    app.after_request(set_csp_header)
    app.after_request(log_request)
    app.errorhandler(429)(ratelimit_exceeded)
    app.errorhandler(413)(payload_too_large)
    app.errorhandler(404)(not_found)
    app.errorhandler(500)(server_error)

    register_cli(app)
    init_database(app)
    if (app.config["MOBILE_AUTH_ENABLED"]
            and os.environ.get("FITX_SKIP_DB_INIT") != "1"):
        from app.services.mobile_auth import validate_derivation_key_readiness
        with app.app_context():
            validate_derivation_key_readiness()
    return app


def register_cognito(app):
    """Cognito Hosted UI/OIDC is disabled for Sprint 1.

    Registration and verification use native backend Cognito API calls through
    app/services/cognito_service.py. No Authlib client is registered and no
    browser redirect to Cognito is supported.
    """
    app.logger.info("[COGNITO] Hosted UI/OIDC disabled; native backend API flow only.")

def register_blueprints(app):
    from app.blueprints.auth import bp as auth_bp
    from app.blueprints.profile import bp as profile_bp
    from app.blueprints.nutrition import bp as nutrition_bp
    from app.blueprints.food import bp as food_bp
    from app.blueprints.menu import bp as menu_bp
    from app.blueprints.training import bp as training_bp
    from app.blueprints.tracking import bp as tracking_bp
    from app.blueprints.social import bp as social_bp
    from app.blueprints.gamification import bp as gamification_bp
    from app.blueprints.supplements import bp as supplements_bp
    from app.blueprints.coach import bp as coach_bp
    from app.blueprints.pages import bp as pages_bp
    from app.blueprints.wearables import bp as wearables_bp
    from app.blueprints.notifications import bp as notifications_bp
    from app.blueprints.challenges import bp as challenges_bp
    blueprints = [
        auth_bp, profile_bp, nutrition_bp, food_bp, menu_bp, training_bp,
        tracking_bp, social_bp, gamification_bp, supplements_bp, coach_bp,
        pages_bp, wearables_bp, notifications_bp, challenges_bp,
    ]
    if app.config["MOBILE_AUTH_ENABLED"]:
        from app.blueprints.mobile_api import bp as mobile_api_bp
        blueprints.append(mobile_api_bp)
    for bp in blueprints:
        app.register_blueprint(bp)
